// src/MapDisplay.js
import React from 'react';
import { GoogleMap, Marker, Polyline, useJsApiLoader } from '@react-google-maps/api';

const containerStyle = {
  width: '100%',
  height: '400px',
};

export default function MapDisplay({ routeData, defaultCenter, zoom = 13 }) {
  const { isLoaded, loadError } = useJsApiLoader({
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY,
  });

  // Show loading / error states
  if (loadError) {
    console.error('Google Maps API load error:', loadError);
    return <div style={{ padding: '1rem', color: 'red' }}>Error loading Google Maps</div>;
  }
  if (!isLoaded) {
    return <div style={{ padding: '1rem' }}>Loading map…</div>;
  }

  // Transform routeData ([lat,lng] arrays) into {lat,lng} points
  const path = (routeData || []).map(([lat, lng]) => ({ lat, lng }));

  return (
    <GoogleMap
      mapContainerStyle={containerStyle}
      center={defaultCenter}
      zoom={zoom}
      options={{ streetViewControl: false, mapTypeControl: false }}
    >
      {path.map((pos, i) => (
        <Marker
          key={i}
          position={pos}
          label={{
            text: String(i + 1),
            color: '#fff',
            fontSize: '12px',
            fontWeight: 'bold',
          }}
          icon={{
            path: window.google.maps.SymbolPath.CIRCLE,
            fillColor: '#357ab8',
            fillOpacity: 1,
            strokeOpacity: 0,
            scale: 16,
          }}
        />
      ))}

      {path.length > 1 && (
        <Polyline
          path={path}
          options={{
            strokeColor: '#357ab8',
            strokeOpacity: 0.8,
            strokeWeight: 4,
          }}
        />
      )}
    </GoogleMap>
  );
}



